def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Parse the grid values and populate the grid
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x][y] = value

    # Initialize the DP table with -1
    dp = [[[-1] * N for _ in range(N)] for _ in range(N)]

    # Define a helper function to use dynamic programming to find the max value
    def dp_helper(x1, y1, x2):
        y2 = x1 + y1 - x2
        if x1 == N or y1 == N or x2 == N or y2 == N or grid[x1][y1] == 0 or grid[x2][y2] == 0:
            return float('-inf')
        if (x1, y1, x2) == (N-1, N-1, N-1):
            return grid[x1][y1]
        if dp[x1][y1][x2] != -1:
            return dp[x1][y1][x2]

        value = grid[x1][y1]
        if (x1, y1) != (x2, y2):
            value += grid[x2][y2]

        dp[x1][y1][x2] = value + max(
            dp_helper(x1 + 1, y1, x2 + 1),
            dp_helper(x1, y1 + 1, x2 + 1),
            dp_helper(x1 + 1, y1, x2),
            dp_helper(x1, y1 + 1, x2)
        )

        return dp[x1][y1][x2]

    return dp_helper(0, 0, 0)

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
