def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    value_map = {}

    # Populate the grid and value_map
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x][y] = value
        value_map[(x, y)] = value

    # Initialize DP table
    dp = [[[float('-inf'), float('-inf')] for _ in range(N + 1)] for _ in range(N + 1)]

    # Fill the DP table
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            dp[i][j][0] = max(dp[i-1][j][0], dp[i][j-1][0]) + grid[i][j]
            dp[i][j][1] = max(dp[i-1][j][1], dp[i][j-1][1]) + grid[i][j]
            if (i, j) in value_map:
                dp[i][j][1] = max(dp[i][j][1], dp[i-1][j][0] + dp[i][j-1][0] + value_map[(i, j)])

    # The answer is the maximum value in the bottom-right corner of the DP table
    return max(dp[N][N][0], dp[N][N][1])

