def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str or N <= 0 or K < 0 or K >= N:
        raise ValueError("Invalid input parameters")

    # Convert the number string into a list of lists of single digits
    digits = [list(num_str[i:i+1]) for i in range(N)]

    # Initialize the DP table with -1
    dp = [[[-1] * (K + 1) for _ in range(N)] for _ in range(N)]

    def dfs(start, end, k):
        if dp[start][end][k] != -1:
            return dp[start][end][k]
        if k == 0:
            return int(''.join(digits[start:end+1]))

        max_val = 0
        for i in range(start, end):
            left = dfs(start, i, k - 1)
            right = dfs(i + 1, end, 0)
            max_val = max(max_val, left * right)

        dp[start][end][k] = max_val
        return max_val

    return dfs(0, N - 1, K)

def max_product(num_str: str, N: int, K: int) -> int:
    if N < K + 1:
        raise ValueError("K is too large for the given number string length.")

    # Convert the string into a list of integers for easier manipulation
    nums = [int(digit) for digit in num_str]

    # If K is 0, no multiplication signs are inserted, return the number itself
    if K == 0:
        return int("".join(map(str, nums)))

    # Initialize a list to store the maximum product of splitting at each position
    max_products = [0] * (N + 1)
    max_products[0] = 1

    # Iterate over each digit in the number string
    for i in range(1, N + 1):
        for j in range(K + 1):
            if j == 0:
                max_products[i] = max(max_products[i], max_products[i - 1] * nums[i - 1])
            else:
                for k in range(1, i):
                    max_products[i] = max(max_products[i], max_products[k] * int("".join(map(str, nums[k:i]))))

    return max_products[N]

def max_product(num_str: str, N: int, K: int) -> int:
    # Convert the string into a list of integers for easier manipulation
    nums = [int(digit) for digit in num_str]

    # If no multiplication signs are allowed, the product is the single number itself
    if K == 0:
        return int("".join(map(str, nums)))

    # If all multiplication signs are allowed, split the number into individual digits
    if K == N - 1:
        return 1

    # Initialize a list to store the maximum product for each possible split
    max_products = [0] * (K + 1)

    # Calculate the maximum product for each split
    for i in range(1, K + 1):
        for j in range(1, N - i):
            left_part = ''.join(map(str, nums[:j]))
            right_parts = [''.join(map(str, nums[j:j + len(sub)])) for sub in sorted([''.join(map(str, nums[j:]))], key=lambda x: int(x), reverse=True)]
            max_products[i] = max(max_products[i], int(left_part) * int(right_parts[0]))

    return max_products[K]

def max_product(num_str: str, N: int, K: int) -> int:
    if N - K - 1 <= 0:
        return 0

    num_str = list(num_str)
    num_str.sort(reverse=True)

    for _ in range(K):
        insert_index = 1
        while insert_index < len(num_str) - 1 and num_str[insert_index - 1] * int(''.join(num_str[:insert_index])) <= num_str[insert_index] * int(''.join(num_str[:insert_index + 1])):
            insert_index += 1
        num_str.insert(insert_index, '*')

    return int(''.join(num_str))

def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str.isdigit() or N != len(num_str) or K < 0 or K > N - 1:
        raise ValueError("Invalid input parameters")

    if K == 0:
        return int(num_str)

    max_product = 0
    for i in range(1, K + 1):
        left_part = num_str[:i]
        right_parts = [num_str[i:]]
        while right_parts:
            current_product = int(left_part)
            for part in right_parts:
                current_product *= int(part)
                right_parts.remove(part)
                max_product = max(max_product, current_product)
                right_parts.insert(0, part)

    return max_product

