def verify_isbn(isbn: str) -> str:
    # Remove hyphens from the ISBN
    isbn = isbn.replace('-', '')

    # Check if the ISBN has exactly 10 characters
    if len(isbn) != 10:
        raise ValueError("Invalid ISBN length")

    # Calculate the checksum
    total = 0
    for i in range(9):
        digit = int(isbn[i])
        total += digit * (10 - i)

    # Check the last character
    if isbn[9] == 'X':
        total += 10
    else:
        digit = int(isbn[9])
        total += digit

    # Check if the checksum is valid
    if total % 11 == 0:
        return "Right"
    else:
        # Calculate the correct checksum digit
        correct_checksum = (11 - (total % 11)) % 11
        if correct_checksum == 10:
            correct_checksum = 'X'
        else:
            correct_checksum = str(correct_checksum)

        # Return the corrected ISBN
        return isbn[:9] + correct_checksum

def verify_isbn(isbn: str) -> str:
    # Remove hyphens from the ISBN
