    # Check if the ISBN has exactly 10 digits
    if len(isbn) != 10:
        raise ValueError("ISBN must have exactly 10 digits")

    # Check if the last digit is a number or 'X'
    if not (isbn[9].isdigit() or isbn[9] == 'X'):
        raise ValueError("The last digit of ISBN must be a number or 'X'")

    # Calculate the checksum
    total = 0
    for i in range(9):
        digit = int(isbn[i]) if isbn[i].isdigit() else 10
        total += digit * (10 - i)

    # Determine if the ISBN is correct
    if isbn[9].isdigit():
        calculated_checksum = total % 11
        provided_checksum = int(isbn[9])
        if calculated_checksum == provided_checksum:
            return "Right"
        else:
            # Generate the corrected ISBN
            corrected_checksum = 11 - calculated_checksum if calculated_checksum != 0 else 0
            return f"{isbn[0:9]}{corrected_checksum}"
    else:
        provided_checksum = 10 if isbn[9] == 'X' else int(isbn[9])
        if total % 11 == 0:
            return "Right"
        else:
            # Generate the corrected ISBN
            corrected_checksum = 'X' if (11 - total % 11) == 10 else str(11 - total % 11)
            return f"{isbn[0:9]}{corrected_checksum}"

def verify_isbn(isbn: str) -> str:
    parts = isbn.split('-')
    if len(parts) != 3 or len(parts[2]) != 5 or parts[2][4] not in '0123456789X':
        raise ValueError("Invalid ISBN format")

    prefix, group, check = parts
    digits = group + check.replace('X', '10')

    sum_ = sum((i + 1) * int(digits[i]) for i in range(10))

    if sum_ % 11 == 0:
        return "Right"
    else:
        correct_check = str((11 - (sum_ % 11)) % 11)
        return f"{prefix}-{group}-{check[:-1]}{correct_check}"

