            if char == '-':
                continue
            if i == 9:
                multiplier = 1 if char == 'X' else int(char)
            else:
                multiplier = 10 - i
            total += int(char) * multiplier
        return total % 11 == 0

    def correct_isbn(isbn: str) -> str:
        digits = [int(char) if char != '-' else 0 for char in isbn]
        for i in range(10):
            digits[9] = i
            if calculate_checksum(''.join(map(str, digits))):
                return isbn[:9] + str(i)
        return isbn

