def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Invalid input: n must be a positive integer and m must be a non-negative integer.")

    if n == 1:
        return 1

    # Create a 2D dp array where dp[i][j] represents the number of ways to return to the starting student
    # after i passes and being at student j
    dp = [[0] * n for _ in range(m + 1)]

    # Initialize the dp array for 0 passes (there's only one way to be at each student without passing the ball)
    for i in range(n):
        dp[0][i] = 1

    # Fill the dp array
    for i in range(1, m + 1):
        for j in range(n):
            dp[i][j] = dp[i - 1][(j - 1) % n] + dp[i - 1][(j + 1) % n]

    # The result is the number of ways to return to the starting student (student 0) after m passes
    return dp[m][0]

def count_passing_ways(n: int, m: int) -> int:
