    # Base case: If there's only one student, there's only one way to pass the ball back to the starting student after 0 passes
    dp[0][0] = 1

    # Fill the DP table
    for passes in range(1, m + 1):
        for student in range(n):
            dp[student][passes] = dp[(student - 1) % n][passes - 1] + dp[(student + 1) % n][passes - 1]

    # The result is the number of ways to return to the starting student after m passes
    return dp[0][m]

