    # Check for smallest prime factor 2
    if n % 2 == 0:
        largest_factor = n // 2

    # Check for odd factors from 3 onwards
    factor = 3
    while factor * factor <= n:
        if n % factor == 0:
            largest_factor = n // factor
        factor += 2

    # If no factors found, n itself is a prime
    if largest_factor is None:
        largest_factor = n

    return largest_factor

