            return 1
        else:
            return 0
    if x == 1 and k == n:
        return 1
    count = 0
    for i in range(x, n // k + 1):
        count += count_partitions(n - i, k - 1, i)
    return count

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or k < 1 or x < 1:
        return 0

    def helper(n, k, x):
        if n < k * x:
            return 0
        if k == 1:
            return 1 if n >= x else 0
        return sum(helper(n - i, k - 1, x) for i in range(x, n // k + 1))

    return helper(n, k, x)

