def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if T == 0 or M == 0 or not herbs:
        return 0

    # Create a 2D DP array where dp[i][j] represents the maximum value
    # that can be obtained with the first i herbs and a time limit of j
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    for i in range(1, M + 1):
        time, value = herbs[i - 1]
        for j in range(1, T + 1):
            if time <= j:
                # If the current herb can be picked, consider the max value by including or excluding it
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - time] + value)
            else:
                # If the current herb cannot be picked, carry forward the previous maximum value
                dp[i][j] = dp[i - 1][j]

    return dp[M][T]

