def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if n == 0:
        return V

    dp = [False] * (V + 1)
    dp[0] = True

    for volume in volumes:
        for j in range(V, volume - 1, -1):
            dp[j] = dp[j] or dp[j - volume]

    max_occupied = 0
    for i in range(V, -1, -1):
        if dp[i]:
            max_occupied = i
            break

    return V - max_occupied

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # dynamic programming table to store maximum volume that can be occupied
    dp = [[0] * (V + 1) for _ in range(n + 1)]

    # fill the dp table
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            if volumes[i - 1] <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - volumes[i - 1]] + volumes[i - 1])
            else:
                dp[i][j] = dp[i - 1][j]

    # maximum volume that can be occupied
    max_occupied_volume = dp[n][V]
    # minimum remaining space
    min_remaining = V - max_occupied_volume
    return min_remaining

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Base case: if no items or no capacity, the remaining space is the total capacity
    if n == 0 or V == 0:
        return V

    # If the volume of the last item is more than the remaining capacity, ignore it
    if volumes[n - 1] > V:
        return min_remaining_space(V, n - 1, volumes)

    # Recurrence relation: maximize the occupied volume
    return min(
        min_remaining_space(V, n - 1, volumes),  # Exclude the last item
        min_remaining_space(V - volumes[n - 1], n - 1, volumes)  # Include the last item
    )

