        raise ValueError("All volumes must be non-negative and less than or equal to the box capacity V.")

    dp = [0] * (V + 1)

    for volume in volumes:
        for j in range(V, volume - 1, -1):
            dp[j] = max(dp[j], dp[j - volume] + volume)

    max_occupied_volume = dp[-1]
    return V - max_occupied_volume

