        n = len(arr)
        dp = [1] * n
        for i in range(1, n):
            for j in range(i):
                if arr[i] > arr[j]:
                    dp[i] = max(dp[i], dp[j] + 1)
        return max(dp)

    # Find the maximum length of the increasing subsequence
    max_increasing = lis(heights)

    # Reverse the heights to find the maximum length of the decreasing subsequence
    reversed_heights = heights[::-1]
    max_decreasing = lis(reversed_heights)

    # The minimum number of students to leave is the total number of students
    # minus the length of the longest increasing subsequence plus the length of
    # the longest decreasing subsequence minus 1 (since the student at position
    # 'i' is counted twice in the sum of the two subsequences)
    return n - max_increasing - max_decreasing + 1

